export const meta = {
  name: 'cam-live-build-wave1',
  description: 'CAM Live 1.0 build: neural model, prediction, reward meta-learning, credit, computer harness, runtime (12 agents, shared worktree, disjoint paths)',
  phases: [
    { title: 'Build', detail: 'A model, B/C/D tensor-level parts, four harness workstreams, runtime' },
    { title: 'Model integration', detail: 'B, C, D wired onto the real model after A lands' },
  ],
}

const ROOT = '/workspace/camlive'
const P = ROOT + '/cam_live'
const OLD = '/workspace/agentrs/superlearner/src/superlearner'

function common(id, paths, specParts) {
  return [
    'You are workstream ' + id + ' of the CAM Live 1.0 build: a standalone project inside the git worktree ' + ROOT + ' (branch feat/cam-live, package directory ' + P + '). A master agent owns the shared contracts and will integrate all workstreams afterwards. Other workstream agents are editing other directories of this same worktree at this moment.',
    '',
    'READ FIRST, in this order:',
    '1. ' + P + '/docs/CAM_LIVE_ARCHITECTURE.md  (binding: ground rules, ownership table, design decisions and the lessons behind them, engineering rules, status-file schema).',
    '2. Your parts of the operator specification ' + P + '/docs/CAM_LIVE_SPEC.md : ' + specParts + '. Read those line ranges in full; they are the requirements.',
    '3. The master-owned code contracts (do not edit them): src/cam_live/contracts.py, src/cam_live/nn/api.py, src/cam_live/config.py, src/cam_live/learning_api.py, src/cam_live/diagnostics/world.py, src/cam_live/diagnostics/tabular.py, src/cam_live/harness/__init__.py, src/cam_live/harness/rpc.py, tests/conftest.py.',
    '4. Your requirement ids: the entries with "workstream": "' + id + '" in ' + P + '/docs/CAM_LIVE_COMPLETION_MANIFEST.json.',
    '',
    'HARD RULES (details in the architecture document sections 0 and 8):',
    '- Edit ONLY your own paths: ' + paths + ' ; plus docs/' + id + '/, docs/evidence/' + id + '/, docs/status/' + id + '.json, docs/change_requests/' + id + '.md, docs/evidence/test_results/' + id + '*.xml. If a master-owned contract is wrong or missing something, write a change request (what, why, exact proposed diff) and work around it inside your own code meanwhile.',
    '- Standalone: never import superlearner, crucible or agentrs. You MAY copy tested code from /workspace/agentrs (read-only for you) into your own files with a provenance comment.',
    '- No placeholders, no stubs, no tests that only exercise fakes of your own code. If something cannot be finished, say so in your status file under not_done; never present it as done.',
    '- No strategy content anywhere (no community-growth tactic, niche, schedule, marketing or psychological framework), and nothing returns a scalar reward to the learner.',
    '- Python is ' + ROOT + '/.venv/bin/python . Run tests as: cd ' + ROOT + ' && .venv/bin/python -m pytest cam_live/tests/<your dir> -q --rootdir=cam_live . Default tests must be CPU-only, seeded and fast; mark gpu / slow / browser / privileged / network otherwise (those run only with -m).',
    '- The GPU is shared with another project. Models under 4 GB may use it freely; anything loading Qwen3-4B or using more than 4 GB must take the shared lock through tests/conftest.py (gpu_lock / the gpu_heavy fixture) or the same fcntl.flock on cam_live.config.GPU_LOCK_PATH in scripts, hold it at most about 15 minutes, stay under 24 GB, and free memory afterwards. Never wrap pytest itself in flock.',
    '- Do not touch /workspace/agentrs, its virtualenv, other worktrees or any running process. Do not git push. No calls to external services except PyPI, Hugging Face downloads and read-only fetches of public documentation you need. Never call the Discord API and never post anything anywhere.',
    '- Extra Python packages: install only with: uv pip install --python ' + ROOT + '/.venv/bin/python <pkg> , and list them in your status file.',
    '- Commit early and often, only your own paths, on the current branch: git add <your paths> && git commit -m "cam live [' + id + ']: <what>" -- <your paths> . Retry if the index is locked. Never git add -A, never amend, rebase, stash, checkout or reset.',
    '- If you find existing work in your paths from an interrupted earlier run of this same workstream, continue from it instead of restarting.',
    '- Be economical with tokens: code and tests are the deliverable; keep prose minimal; do not re-read large files you already read.',
    '',
    'WHEN DONE: (1) run your tests one final time writing JUnit XML to cam_live/docs/evidence/test_results/' + id + '.xml (--junitxml=...); (2) write cam_live/docs/status/' + id + '.json following the schema in section 9 of the architecture document, one entry per requirement id you own, honest states (implemented / partial / not_started), exact test node ids, measured numbers with the commands that produced them, not_done and scientific_failures lists; (3) commit; (4) return a summary of at most 350 words: what exists, the public API another workstream must know (exact signatures), measured numbers, what is NOT done, change requests filed.',
    '',
  ].join('\n')
}

const A = common('A', 'src/cam_live/nn/ (except api.py), tests/nn/', 'Part 1 (lines 173-294), Part 2 (295-389), Part 3 (390-449), section 16.10 (inside 2116-2277)') + [
  'YOUR JOB: Workstream A, the neural architecture. Implement cam_live.nn.model.CamLiveModel(LatentModelAPI) and build_model(cfg: CamLiveConfig) exactly per src/cam_live/nn/api.py and architecture section 2.',
  '',
  'Modules to deliver (you choose internals; names below are the public surface other workstreams will import):',
  '- nn/backbone.py: SemanticBackbone for Hugging Face causal LMs (default Qwen/Qwen3-4B at the pinned local snapshot under HF_HOME=/workspace/.hf_home, bf16, frozen) and TinyBackbone (name "tiny": small random causal transformer LM with a simple deterministic tokenizer, same interface, CPU, used for mathematical and gradient-path tests only). Both support: multi-depth mean-pooled embeddings (cfg.backbone.tap_layers) with a text-hash cache that is bypassed for with_grad=True and invalidated when adapters change; LoRA adapters across layers sized to 10-20M trainable parameters on Qwen3-4B (your own LoRA layers or peft, your choice; report the exact count); the latent bridge (belief b -> cfg.backbone.bridge_tokens virtual prefix embeddings, zero-initialised so it is an exact no-op at init); generate(...) with the bridge; generation_logprob(...) differentiable w.r.t. adapters, bridge and latent; gradient checkpointing for the adapter path. A reference loading pattern exists in ' + OLD + '/cam_unified/semantic/encoder.py and a gated latent cross-attention in cam_unified/semantic/decoder_xattn.py (if you use it, the gate must start at exactly zero).',
  '- nn/tokens.py: ExperienceTokenizer (nn.Module) and to_items(record, **kw) -> List[ExperienceItem] converting every contract record type into experience items (Observation, ActionSpec, ActionResult, OutcomeQuery+OutcomeObservation pairs, PredictionRecord, ToolDescriptor, TaskSpec objective as GOAL, Cost, failures, entities). Separate value channel for exact quantities (sign, symlog magnitude at several scales, hashed metric-name embedding), separately normalised before fusion; continuous-time encoding from absolute seconds (use differences to the newest token, log-scaled, so 1 second and 30 days are both resolvable); raw values preserved in TokenBatch.values.',
  '- nn/core.py: ExperientialCore (RMSNorm, SwiGLU, causal self-attention with rotary positions, elapsed-time conditioning, cross-attention to persistent state slots, gated slot update, direct current-event path into b).',
  '- nn/fast.py: FastBeliefState and its learned prior (nn.Module in the experiential group): Bayesian last-layer posterior over phi per outcome kind. Gaussian: exact conjugate update, float64, Joseph or Cholesky form. Count / binary / time-to-event with right-censoring: assumed-density (Laplace / EKF) GLM updates with exposure. Forgetting factor and a simple change detector for changing mechanisms. API to provide: predict(phi, kind) -> mean, epistemic variance, noise/dispersion; update(phi, y, kind, exposure=None, censored=None) -> dict with surprise and KL (belief change); sample_weights(n, kind, generator); reset(); clone(); state_dict()/load_state_dict(); plus a differentiable functional form (posterior update as a pure function of tensors) so the prior and the features can be trained ALPaCA-style through online updates. A numerically exact reference exists in ' + OLD + '/cam7/posterior.py and cam_unified/core/bayes.py.',
  '- nn/fast_compare.py: a runnable experiment (python -m cam_live.nn.fast_compare) on synthetic meta-regression task families with held-out families comparing: the learned-prior Bayesian layer, exact Bayesian linear regression on raw inputs, a GRU adapter, and running statistics, for Gaussian and count targets. Write docs/evidence/A/fast_adaptation.json and report the result honestly even if the learned prior loses (it lost in earlier projects; train with each task full-data scale, not the support-estimated spread).',
  '- nn/model.py: CamLiveModel assembling everything, parameter groups exactly per nn.api.GROUPS, register_head, count_parameters (frozen, experiential, adapters, reward, each head, total persistent trainable), group_hashes, trainable_state / load_trainable_state (strict and tolerant), arch_signature. The experiential group at scale "50m" must land near 50M parameters (within about 10 percent; adjust d_ff / layers in your own preset table inside nn/ if the config presets miss, and file a change request with the corrected numbers) and every other preset near its target.',
  '- nn/bench.py: python -m cam_live.nn.bench writes docs/evidence/A/params.json with the measured parameter counts for every preset (experiential part built on CPU) and, under the GPU lock, the real Qwen3-4B configuration: frozen count, adapter count, experiential count, load time, GPU memory, embedding throughput, generation tokens per second with and without the bridge, and memory of one adapter backward pass (batch 4, 256 tokens).',
  '',
  'Tests you must write and pass (tests/nn/): API shapes and dtypes; causality of h (changing a later token never changes earlier h); the value channel separates +1 from -1 (cosine well below 0.5) and exact values survive in TokenBatch.values; the persistent state is learnable (a short training run solves an 8-step recall task well above chance; state is not ~constant at init); gradients reach experiential parameters; LoRA parameters receive nonzero gradient from BOTH the embedding path (embed_texts(with_grad=True) through a downstream loss) and generation_logprob, while frozen backbone parameters have requires_grad False and no grad; the bridge is an exact no-op at initialisation (identical logits with and without latent) and changes generation probabilities after one optimisation step; a permuted belief b changes the decision latent z; parameter groups are disjoint and cover every parameter; trainable_state round-trips bit-exactly and tolerant loading reports missing keys for a newly registered head; group_hashes change after an optimizer step; fast-state numerics against closed form (including many collinear updates), GLM updates converge to the generating weights, forgetting tracks a mechanism change, censored time-to-event handled; preset parameter counts. gpu-marked tests with the real Qwen3-4B: frozen about 4.0B, adapters within 10-20M, experiential near 50M, nonzero adapter gradients through both paths, bridge no-op at init, generate returns text.',
  '',
  'Known pitfalls from earlier projects that you must design against: content norm swamping numeric values; ungated persistent state that was 99.5 percent constant and decayed; a core that could not read the current event through attention-mixed history; a text-initialised soft prefix leaking into generations; semantic-side gradients 100-1000x the core (keep group-wise scales sane and expose groups so the learner can clip per group); ill-conditioned features (normalise phi, small non-zero output init).',
].join('\n')

const B1 = common('B', 'src/cam_live/predict/, tests/predict/', 'Part 3 (390-449), Part 4 (450-518), Part 5 (519-577), Part 6 (578-671), Part 8 (872-908), section 11.1 (inside 1103-1174)') + [
  'YOUR JOB: Workstream B stage 1 of 2 (prediction and decision-making), the tensor-level and model-independent parts. A second agent (stage 2) will wire your modules onto the real model once Workstream A delivers it, so make the public API clean and document it in docs/B/API.md. Everything here is a pure function or nn.Module of the tensors defined in src/cam_live/nn/api.py (b, e_a, a_mask, e_g, e_q, q_mask, kind_ids, horizon_s, z, phi) and is tested with synthetic tensors and synthetic data-generating processes with known ground truth.',
  '',
  'Deliver:',
  '- predict/dists.py: predictive families and exact log-likelihoods with masks: normal and Student-t; negative binomial and Poisson with exposure; Bernoulli with logits; discrete-time hazard for time-to-event with right-censoring (survival function, expected time, censored likelihood); categorical. Conversion to and from contracts.Distribution; mean / std / quantiles / sampling; tests against scipy.',
  '- predict/world.py: WorldHeads(nn.Module): given z [B,N,D], e_q [B,N?,Q,D or B,Q,D], kind_ids, horizon_s (and phi) produce per-kind distribution parameters for every (candidate, query), with a small bootstrapped ensemble or an equivalent explicit epistemic estimate, plus a latent transition head z,dt -> predicted next belief for imagination with its own uncertainty. world_nll(...) with masks for pending / unobservable targets and per-kind normalisation so no kind dominates. Multi-horizon by construction (horizon is an input). Synthetic learning tests: recovers action-conditioned count rates and delayed effects from data; pending targets contribute exactly zero gradient; epistemic uncertainty shrinks with data and is larger off-distribution.',
  '- predict/evaluator.py: GoalEvaluator(nn.Module): success logit from (b, e_g, horizon, policy context features), magnitude head (count or real), time-to-achievement hazard head with censoring, resource head; losses with stable BCE-with-logits; prefix training utility (apply an eventual verified outcome to every earlier prefix of the trajectory); delta_v(b_prev, b_next, ...) exposed as a signal, explicitly not a reward; an action-quality estimate separated from the raw outcome (for example advantage of the chosen action against the policy-weighted candidate set under the model, so a lucky success and a good decision are distinguishable). Synthetic tests: an over-confident evaluator receives corrective gradients and its calibration improves.',
  '- predict/calibration.py: Brier, NLL, calibration slope and intercept (logistic recalibration), reliability bins, expected calibration error, grouped by objective family and horizon, with studentised confidence intervals; a guard that refuses predictions whose made_at is not strictly before the outcome time.',
  '- predict/policy.py: CandidatePolicy(nn.Module): logits [B,N] over a variable candidate set from z (and a value head V and per-candidate Q), masked softmax; select(...) implementing Thompson sampling (given per-candidate posterior samples), UCB, greedy, information-gain weighted, and explicit randomised assignment over arms, each returning the full probability vector actually used (exact propensities, epsilon-floor so every feasible candidate keeps support); a functional forward usable with torch.func.functional_call (the reward workstream differentiates through policy updates). Tests: propensities sum to one and match empirical frequencies; permuting b across the batch changes the distribution (not a constant function of the candidates alone).',
  '- predict/voi.py: decision-relevant value of information for a Bayesian linear-Gaussian posterior and for the GLM cases by sampling: VOI(a) = E_y[max_a Q(b_updated(a,y), a)] - max_a Q(b, a), net of cost, elapsed time and opportunity cost; knowledge-gradient closed form as a check; DownstreamValueEstimator(nn.Module) trained to predict realised downstream usefulness, with a scoring function comparing its estimates to realised downstream learning. Tests: an unpredictable but irrelevant (noisy) observation has near-zero VOI while raw surprise is high; an informative probe has positive VOI; VOI ranks probes by realised downstream regret reduction on a synthetic bandit family.',
  '- predict/registry.py: PredictionRegistry (JSONL-backed, append-only): register PredictionRecords before outcomes, resolve them exactly once, reject resolution earlier than made_at and reject edits of an existing prediction; ExperimentRegistry for contracts.ExperimentRecord (hypothesis and predictions registered before acting; arms; randomised assignment with recorded probabilities; maturity; supported / not supported with the test used and alternative explanations slot).',
  '- predict/candidates.py: strict parsing of model text into typed ActionSpec (JSON only, schema-validated against ToolDescriptor.arg_schema, multi-step programs via steps, rejection reasons recorded); a deterministic schema-walker that enumerates or samples valid argument settings from JSON Schema (integers, enums, numbers, strings from a supplied vocabulary) so candidate sets never depend only on what a language model writes; provenance on every candidate; a prompt builder that renders tool descriptors and an observation digest as DATA (environment text is quoted and never mixed into instructions). Reference implementations you may copy from: ' + OLD + '/cam_unified/selfeval/evaluator.py, selfeval/voi.py, cam7/posterior.py.',
  '',
  'Pitfalls from earlier projects to design against: zero-initialised output layers that blocked critics (use small random init); a twin-Q all-candidate actor chasing critic error; all-zero rewards collapsing an advantage-weighted actor into self-imitation; learned exploration never beat computed VOI on new worlds (keep the computed VOI as the reference and make any learned estimator prove itself); imagination must never decode strings.',
].join('\n')

const C1 = common('C', 'src/cam_live/reward/, tests/reward/', 'Part 7 (672-871) in full, Part 8 (872-908), section 11.4 (inside 1103-1174), sections 16.5-16.6 (inside 2116-2277)') + [
  'YOUR JOB: Workstream C stage 1 of 2 (learned intrinsic reward and meta-learning): the mathematics and the model-independent machinery. A stage-2 agent will wire it onto the real model. Document the public API in docs/C/API.md.',
  '',
  'Study first: Zheng et al. 2020, What Can Learned Intrinsic Rewards Capture (https://proceedings.mlr.press/v119/zheng20b.html and its supplement) and the earlier analysis in /workspace/agentrs/superlearner/docs/CAM_UNIFIED_REWARD_CREDIT_RESEARCH.md (read the sections on meta-gradient bias, the inner-data score term, leave-one-out baselines, and why Zheng assumptions do not hold for an observation-only agent). Verified reference code you may copy: ' + OLD + '/cam_unified/credit/meta_exact.py, credit/lifetime_exact.py, selfeval/metagrad.py, selfeval/intrinsic.py. The exact tabular MDP library is already available as cam_live.diagnostics.tabular.',
  '',
  'Deliver:',
  '- reward/exact.py: exact tabular lifetime meta-gradient reference: intrinsic reward table R_psi, K exact inner policy-gradient updates theta_k(psi), exact outer objective J(psi) = expected EXTRINSIC (verified) return of theta_K, exact dJ/dpsi by automatic differentiation through the unroll, finite differences, and a sampled truncated estimator including the inner-data score term and leave-one-out baselines. Tests (float64): exact gradient equals finite differences to tight tolerance for K in 1,2,4,8; detaching the intrinsic reward inside the inner update gives exactly zero; removing the unroll (stop-gradient on theta_K) gives exactly zero; the sampled estimator is unbiased within z-score bounds AND small relative error at the largest sample size (cosine similarity alone is not accepted: it hid a 60 percent bias before); truncation bias is measured and reported for K=1,2 versus longer lifetimes; meta-training the reward on key-to-door style MDPs makes the learned reward value the delayed-payoff action and beats training on the extrinsic reward alone in learning speed (report honestly).',
  '- reward/meta.py: the general differentiable engine used at CAM scale. MetaGradient over closures and parameter dictionaries with torch.func.functional_call: inner_update(theta: dict, psi_params, support_batches, inner_lr, K, create_graph) implementing theta_next = theta - alpha * grad_theta L_inner(theta; psi, D_support) for an arbitrary differentiable L_inner supplied as a callable; outer objective as a policy-gradient surrogate on query data, sum of log pi_theta_K(a_q) * (U_verified - baseline), with (a) on-policy mode when query actions were sampled from theta_K and (b) importance-weighted mode with clipped weights and an explicit support check (returns unsupported instead of an estimate when logged propensities are missing or effective sample size is too small), plus the inner-data score term when support actions were sampled from the policy being differentiated. Options: truncated unroll K in 1,2,4,8; first-order approximation for comparison; gradient checkpointing of the unroll; float64 path for tests. Tests on a small neural policy (MLP over random features) on a bandit-lifetime problem: gradient matches finite differences in float64 with relative error under a few percent; nonzero meta-gradient reaches every reward parameter; zero when the pathway is cut; memory and time per K reported in docs/evidence/C/meta_cost.json.',
  '- reward/signals.py: the named signal vector consumed by the reward generator (names, order, normalisation hints): success estimate before and after, delta V, action-quality estimate, information gained (belief change), VOI estimate, cost terms (money, seconds, compute), elapsed time, prediction error (standardised), epistemic uncertainty before and after, execution status and failure class one-hot, verified-progress delta when available, novelty of the decision context. A dataclass with to_tensor and a fixed versioned schema.',
  '- reward/intrinsic.py: IntrinsicReward(nn.Module) R_psi(b_t, e_a, b_next, e_g, signals, life_ctx): nonlinear, bounded output (scaled tanh), input normalisation whose statistics can be frozen inside a meta window, version string that changes when parameters change (hash based), and LifetimeContext (a recurrent summary of the lifetime that is not reset at objective boundaries; its state is part of the checkpoint). meta_parameters() returns exactly the reward group.',
  '- reward/bootstrap.py: the cold-start signal, clearly labelled bootstrap: self-supervised predictive learning progress (improvement of prediction loss on the same targets, not raw error), grounded delta V from the evaluator, uncertainty-aware exploration bonus tied to epistemic (not aleatoric) uncertainty, and sparse verified-outcome terms. RewardMixer: r = mix * r_bootstrap + (1 - mix) * r_learned, with mix starting at 1.0 and a promotion rule that lowers it only when held-out verified query evidence shows the learned reward does not hurt (and raises it back otherwise); every use logs which component produced what.',
  '- reward/windows.py: support and query windows cut from one long lifetime: temporal separation, grouping of correlated observations by experiment / parent decision so the number of independent verified outcomes is counted correctly (not rows), eligibility rules, minimum independent outcomes before a meta-update, deterministic window ids.',
  '- reward/integrity.py: guards and their tests: the inner loss can never change psi (assert no gradient and no optimizer overlap); output bounds and scale normalisation so inflating reward magnitude cannot change the induced policy update; de-duplication of outcomes by dedup_key; verifier signature required for any outcome used by the outer objective; rejection of imagined or self-authored outcomes; discounting of repeated trivial self-generated goals; a noisy-TV check (reward for irreducible randomness decays as epistemic uncertainty stops falling); tamper-evident hashing of the outcome ledger used for meta-learning.',
  '',
  'Design constraints: the reward network never sees the extrinsic verified return directly at the time it rewards an action (it sees the signals above); second-order differentiation happens only over a small adaptable parameter subset and cached latents, never through the backbone; world-model and evaluator losses are self-supervised and do not depend on psi.',
].join('\n')

const D1 = common('D', 'src/cam_live/credit/, tests/credit/', 'Part 2 (295-389), Part 9 (909-1016), Part 10 (1017-1102), section 12A.9 temporal abstractions (inside 1343-1779), section 15.2 (inside 2026-2115)') + [
  'YOUR JOB: Workstream D stage 1 of 2 (retrospective credit and continual learning): durable storage, linking, the credit estimators at reference level, and checkpoint IO. A stage-2 agent will build the continual learner on the real model. Document the public API in docs/D/API.md.',
  '',
  'Study first: RUDDER (https://arxiv.org/abs/1806.07857), COCOA (https://arxiv.org/abs/2306.16803, code https://github.com/seijin-kobayashi/cocoa) and the earlier analysis in /workspace/agentrs/superlearner/docs/CAM_UNIFIED_REWARD_CREDIT_RESEARCH.md (bias of return-conditioned hindsight, why the redistributed return-to-go must be used, squared loss on the scaled return, the policy-logit prior and elapsed-time input of the hindsight model). Verified reference code you may copy: ' + OLD + '/cam_unified/credit/estimators.py, credit/heads.py, credit/longdelay.py, memory/_fs.py, memory/checkpoint.py, memory/replay.py. The exact tabular MDP library is cam_live.diagnostics.tabular.',
  '',
  'Deliver:',
  '- credit/replay.py: SqliteExperienceStore implementing contracts.ExperienceStore exactly (SQLite in WAL mode plus a blob directory for large artifacts by reference; single-writer lock; crash-safe: a killed writer loses no acknowledged record): items, experience records (append / update / get / by_decision), pending queries with due times, outcomes with de-duplication by dedup_key, windows, provenance (live / staging / diagnostic are separate strata that are never mixed unless asked), model and reward versions, per-loss eligibility, and sample(n, loss=..., strata=...) balancing recent, informative older (by stored surprise / credit magnitude), successes, failures, delayed-outcome and objective-family strata with seeded determinism. state_dict of sampler indices for checkpoints. Tests include a kill -9 durability test and a test that the sampler does not collapse onto recent successes.',
  '- credit/links.py: OutcomeLinker: attaches delayed outcomes and events to earlier decisions using evidence only (attribution keys inside event data such as by_action, artifact ids, experiment arms, declared attribution windows); when evidence is ambiguous it produces fractional links with explicit uncertainty; it never defaults to the most recent action; it refuses to link an outcome to a decision made after the outcome time (no future leakage) and records what information was available at decision time. Retrospective update queue: when an outcome matures, the affected earlier experience records are marked for re-training.',
  '- credit/estimators.py + credit/exact tests: exact finite-action reference estimators on tabular MDPs: REINFORCE, all-actions, COCOA with exact contribution coefficients w(s,a,u) = p(a | s, u) / pi(a | s) - 1, and RUDDER exact redistribution; each validated against enumerated exact gradients (unbiasedness by z-score and relative error; variance comparison on key-to-door and long-delay tasks).',
  '- credit/rudder.py: ReturnDecomposer(nn.Module): causal sequence model F_xi over per-decision latents predicting the eventual verified return from every prefix; squared loss on the scaled return; redistributed contributions c_t = F(H_t+1) - F(H_t) with the initial offset and a residual correction so that contributions sum exactly to the realised return; duration-aware discounting exp(-beta * dt) with a conservation test under that convention; redistributed return-to-go as the learning signal; never fabricates return: unmatured trajectories produce no redistributed credit. Tests on synthetic delayed-reward sequences: conservation to numerical precision, the key decision receives the credit, pending sequences yield nothing.',
  '- credit/cocoa.py: HindsightModel(nn.Module) h(a | b, u, elapsed) over probability-tracked candidate sets with the logged policy logits as prior; contribution coefficients w = h / pi - 1 with clipping; uncertainty from an ensemble or from the support (effective sample size per candidate); a support check that returns UNSUPPORTED rather than a number when propensities are missing, a candidate had near-zero logged probability, or the action space is open-ended without tracked proposals; outputs keep three separate fields: learned association, counterfactual estimate, experimentally supported effect (filled only from randomised arms). Tests on tabular problems against the exact coefficients.',
  '- credit/simple.py: the simple delayed-outcome attribution used first in live operation (evidence links, time-decayed windows, randomised-arm differences with confidence intervals), and credit/select.py: an evidence-based selector that compares each estimator with randomised-experiment differences where available and only then promotes it to the training default; the selection and its evidence are logged.',
  '- credit/smdp.py: temporally extended actions: an experience record at intervention level contains the primitive and procedure traces; duration-aware discount; a guarantee (tested) that one outcome is credited once across the three timescales.',
  '- credit/checkpoint.py: atomic checkpoints (temporary directory, fsync, rename, previous kept, recovery after a crash between renames) holding: trainable weights by group (safetensors), optimizer states, fast adaptive state, lifetime context, current task, replay sampler indices, pending outcomes pointer, learning schedules, RNG states, authorization-config hash, model / reward versions, architecture signature; tolerant loading when new heads were added (reported, not silent); weights-only export and load for transfer evaluation (nothing but neural parameters and fixed configuration); CheckpointManager with promotion gated by supplied validation and retention metrics and rollback to the last promoted checkpoint. Tests with plain nn.Modules now (stage 2 wires the real model): kill during save leaves a loadable checkpoint; round trip is bit exact; weights-only export contains no experience, memory or optimizer state.',
  '',
  'Pitfalls from earlier projects: checkpoints that broke whenever a module was added; a reservoir that almost always replaced old entries; a RUDDER decomposition used as an immediate reward gave the key decision zero credit; symlog plus smooth-L1 return regression broke redistribution optimality; replay provenance copied per update at huge cost.',
].join('\n')

const HARN = 'Part 12 (1175-1342), Part 12A (1343-1779) in full, the autonomous obstacle resolution section (1780-1805)'

const EB = common('EB', 'src/cam_live/harness/env.py, harness/service.py, harness/browser.py, harness/perception.py, harness/internal.py, harness/staging/, tests/harness/env/, docs/HARNESS_ADAPTER_GUIDE.md', HARN) + [
  'YOUR JOB: Workstream EB: the computer environment core. Other harness workstreams run in parallel: EC (sandbox, jobs, visual, grounding models), EA (authorization service, vault, launcher), ES (skills, modality selection, failure taxonomy, publishing, Discord, HTTP API). You integrate with them only through contracts.ModalityExecutor, contracts.ExecContext and contracts.PolicyEngine.',
  '',
  'Deliver:',
  '- harness/env.py: ComputerEnvironment implementing contracts.EnvironmentAdapter by composing registered ModalityExecutor objects (register(executor)); routes an ActionSpec (and programs via steps) to the executor of its modality; verifies the AuthorizationDecision with PolicyEngine.check_grant before anything runs and passes PolicyEngine.check_primitive into ExecContext.check so every primitive operation of every modality is checked; owns observation ids and staleness (an action referring to an element of an outdated observation fails with FailureClass.STALE_OBSERVATION), the event stream and cursor for poll_events, pending OutcomeQuery bookkeeping and measure(), resource accounting, evaluation of ActionSpec.verify against the resulting state after consequential actions, complete execution logging (every action, primitive op, result and observation appended to the run directory events log, with secrets scrubbed through the ExecContext.secrets broker if present), persistent workspace directory, and restart recovery (state file; pending outcomes, cursors and browser sessions survive a process restart). Coordination: operations that modify shared external state are serialised and de-duplicated by action id (the same action is never executed twice even if submitted twice or after a crash-retry); read-only work may run concurrently.',
  '- harness/service.py: process entry point (python -m cam_live.harness.service --run-dir R --socket R/sock/exec.sock --auth-socket R/sock/auth.sock) exposing the environment over cam_live.harness.rpc as ExecRPC v1 (the EnvironmentAdapter methods plus ping and close), and RemoteEnvironment, a client class implementing EnvironmentAdapter over that socket; plus a RemotePolicy client implementing PolicyEngine over the auth socket (method names exactly those of the PolicyEngine protocol). Version negotiation on connect.',
  '- harness/browser.py: structured_browser executor on Playwright Chromium (chromium 159 is installed for this venv; in this container launch with --no-sandbox; when the cambrowser system user exists and you are root, run Chromium under that uid with a profile directory only it can read, via an executable wrapper using setpriv, otherwise run in-process uid). Persistent context per authorized identity (cookies survive restart), multiple tabs, isolated incognito contexts for read-only research, connect to an external Chromium over CDP (connect_over_cdp) as well as native launch. Observation per spec 12A.2: URL, title, bounded visible-text digest, accessibility tree, relevant DOM structure, interactive elements with semantic roles and stable per-observation element refs, form fields, links, tabs, diff against the previous observation, observation id; screenshots only on demand. Primitives: navigate, open/close/select tab, inspect, read, click(ref), fill(ref, text), select_option, press key, scroll, upload (authorized file only), download (authorized), wait_for (state change). Semantic locators first (role/name), fallbacks recorded. A screen() object exposing screenshot() -> PNG bytes, size(), click(x, y), double_click, drag, scroll(dx, dy), type(text), key(combo) for the visual executor of workstream EC. Navigation and downloads go through ExecContext.check per URL. A DOM extractor exists in /workspace/agentrs/src/agentrs/environments/web/playwright_env.py (and dom_extract.js) and crucible/src/crucible/web/browser.py that you may copy.',
  '- harness/perception.py: the unified perception interface (12A.5): converts browser observations, tool results, documents (HTML, text, PDF text if available, CSV, JSON), images (dimensions and reference; no model needed), execution traces and events into contracts.Observation with exact quantities extracted as Quantity objects (numbers in tables / metrics preserved exactly with units), provenance, trust level untrusted, and compact page-state differences to avoid re-encoding unchanged pages.',
  '- harness/internal.py: the internal executor: wait (schedules, does not burn inference or produce public activity), inspect own records, note.',
  '- harness/staging/: local controlled web services for acceptance tests (started on localhost ports; labelled staging in get_capabilities): (1) a structured HTML application with forms, tables and a multi-step workflow; (2) the same functions rendered only as canvas-drawn visual controls (no DOM semantics) for visual computer use; (3) a page whose content changes dynamically after load and after actions; (4) an unfamiliar-interface variant set: at least two alternative layouts of the same task with different labels, ids and structure, plus a mid-run interface change switch for skill-staleness tests; (5) labsite: cam_live.diagnostics.world.LabWorld behind a web UI and JSON pages, so delayed consequences can be exercised through the browser. Keep all staging content abstract and neutral (no community, marketing or growth semantics).',
  '- docs/HARNESS_ADAPTER_GUIDE.md: how an operator plugs in a different browser or tool harness (implement ModalityExecutor or a whole EnvironmentAdapter, register tools, what the learner assumes, how to run the contract tests against it).',
  '',
  'Tests (tests/harness/env/, browser-marked ones must really launch Chromium): environment contract conformance; every primitive against the staging sites; stale-reference detection; multi-step workflow end to end on the structured site and on an unfamiliar variant; dynamic change observed through diffs; persistent session survives environment restart; CDP attach to a separately launched Chromium; denial path (a policy that denies a URL prevents navigation and the result is DENIED with a hard failure class, with no fallback to another modality); duplicate submission of the same action executes once; perception keeps exact numbers; a page containing text that instructs the agent to change its goal or reveal secrets is returned as untrusted data and changes nothing in the environment; RPC round trip of the whole adapter; execution log completeness.',
].join('\n')

const EC = common('EC', 'src/cam_live/harness/sandbox.py, harness/jobs.py, harness/visual.py, harness/grounding/, tests/harness/compute/', HARN) + [
  'YOUR JOB: Workstream EC: sandboxed code execution, background jobs, visual computer use and visual-grounding models. Parallel workstreams: EB (environment adapter, browser; it will expose a browser screen() object with screenshot() -> PNG bytes, size(), click(x, y), double_click(x, y), drag(x1, y1, x2, y2), scroll(dx, dy), type(text), key(combo)), EA (authorization), ES (skills and connectors). You integrate through contracts.ModalityExecutor and contracts.ExecContext only; define the ScreenProvider protocol with exactly those method names in harness/visual.py and write a small Playwright-page-backed ScreenProvider inside your tests so you do not depend on EB.',
  '',
  'Deliver:',
  '- harness/sandbox.py: the code executor (modality "code"): tools sandbox.python, sandbox.shell, sandbox.write_file, sandbox.read_file, sandbox.list_files operating in a persistent isolated workspace. Isolation available in this unprivileged container: a dedicated uid (system user camsbx via cam_live.harness.uid_of("sandbox") when it exists and you are root; clearly reported weaker mode otherwise), rlimits (CPU, address space, processes, file size, open files), Landlock filesystem scoping to the workspace, seccomp (no network sockets by default, no ptrace / mount / namespace / bpf), no_new_privs, a clean environment with no credentials, wall-clock timeout with process-group kill, output truncation. A verified implementation of exactly this (rlimits + uid drop + Landlock + seccomp) exists in /workspace/agentrs/crucible/src/crucible/sandbox/runner.py : copy and adapt it. A scoped-network mode for jobs that are authorized to reach the network must route every outbound request through ExecContext.check (for example a local allowlisting HTTP proxy the job is pointed at) and must state honestly in capabilities() which parts are kernel-enforced and which are not. Generated code must not be able to read the credential vault, the browser profile, the verifier or audit logs, the learner checkpoints or anything outside its workspace: prove each with a test (privileged-marked where it needs root).',
  '- harness/jobs.py: bounded background jobs: purpose text, resource limits, deadline, observable status, cancellation, persisted result records in the run directory, concurrency cap, results delivered as events; jobs survive nothing silently (a restart reports interrupted jobs as such).',
  '- harness/visual.py: the visual executor (modality "visual"): screenshot observations (viewport; full page; crops), and primitives click, double_click, drag, scroll, type, key / shortcut by coordinates on a ScreenProvider; every coordinate action is validated against the current screenshot observation id (stale screenshots rejected), screen bounds and ExecContext.check; a grounded action = ask a VisualGrounder for coordinates for an intended target, validate, then execute, then re-observe to verify the effect (never assume success). The grounder output never executes anything by itself.',
  '- harness/grounding/: the replaceable grounding-model interface (contracts.VisualGrounder) with: (a) an integration of HongxinLi/GoClick-Base (https://huggingface.co/HongxinLi/GoClick-Base) as the lightweight candidate; (b) an optional integration of Tongyi-MAI/MAI-UI-2B for harder interfaces; (c) optionally vocaela/Vocaela-2-500M-1024R2. For each: check the actual licence and model card, pin an exact revision hash, read any custom model code before running it (do not use trust_remote_code on code you have not read; note what you reviewed in docs/EC/MODEL_REVIEW.md), download into HF_HOME=/workspace/.hf_home (set HF_HUB_OFFLINE=0 only for the download), keep the models frozen, load lazily, and never load them in a process that holds credentials. If a model cannot be run (licence, missing files, incompatible code), record exactly why and what was tried; that is an acceptable honest outcome for (b) and (c), but make a serious effort for (a). Also provide a non-neural reference grounder for comparison only (for example template or text-box matching on rendered pages) clearly labelled as a baseline.',
  '- harness/grounding/bench.py: python -m cam_live.harness.grounding.bench runs each available grounder on controlled computer-use tasks rendered with Playwright (pages you generate: canvas-drawn buttons, icon-only controls, dense forms, small targets, look-alike distractors, a multi-step visual workflow) and writes docs/evidence/EC/grounding_bench.json with: grounding accuracy, end-to-end operation success (click really changed the page state), incorrect actions, recovery after an error, latency, GPU memory, compute per successful operation. Hold the shared GPU lock only if a model needs more than 4 GB.',
  '',
  'Tests (tests/harness/compute/): sandbox runs Python and shell, enforces every limit (CPU, memory, processes, file size, timeout), blocks network by default, cannot read outside its workspace (including a planted fake secret file and a fake browser profile owned by another uid), leaves no processes behind; background jobs: limits, deadline, cancel, status, persisted results, concurrency cap; visual executor: click / type / drag / scroll on canvas pages with verification of the effect, stale screenshot rejected, out-of-bounds rejected, denied by policy stays denied; grounding interface with the reference grounder on CPU and gpu-marked tests for the neural grounders that were integrated.',
].join('\n')

const EA = common('EA', 'src/cam_live/harness/auth/, tests/harness/auth/', HARN + ', section 13.4 (inside 1806-1911)') + [
  'YOUR JOB: Workstream EA: the independent authorization layer, credential isolation, approvals, limits, audit, emergency stop, process separation and defence against instructions embedded in environment content. This layer sits outside the learner; the learned policy and reward can never change its configuration, keys or logs. Parallel workstreams call you only through contracts.PolicyEngine and ExecContext.secrets.',
  '',
  'Deliver:',
  '- harness/auth/policy.py: PolicyService implementing contracts.PolicyEngine. Fail-closed rule evaluation of an ActionSpec (recursively over steps) and of each PrimitiveOp against a declarative policy file (configs/authorization.yaml is master-owned: write your default policy as src/cam_live/harness/auth/default_policy.yaml and document its schema): task mode (diagnostic / staging / live; live requires an explicit, signed operator authorization record naming the task, accounts, destinations, budgets and time window); permitted modalities and tools per task (TaskSpec.interfaces / resources); allowed and denied destinations (URL hosts and path patterns, API endpoints, accounts, channels, file roots); side-effect classes (none / local / external_read / external_write) with external_write to non-owned destinations denied and to owned destinations requiring approval unless the operator pre-authorized that destination class; publishing approvals; spending limits (per action, per day, total) and resource limits (compute seconds, decisions, external actions); rate limits per destination; data-use permissions (TaskSpec.data_permissions, for example no storage or training use of platform message content, no personal data collection beyond aggregates); platform-compliance rules as data (per-platform rule entries the operator can edit); and structural detectors for the prohibited classes of spec 12.6: unsolicited mass outreach (recipient count / repeated near-duplicate content across destinations / direct messages to non-opted-in recipients), deceptive identity (publishing must carry the configured disclosure where the platform or operator requires it; no impersonation fields), artificial membership inflation, join-for-join, paying or rewarding for engagement or membership, circumvention (an action whose earlier attempt was DENIED may not be re-issued through another modality or with cosmetic changes: track denied intents by normalised target and effect), credential leakage (secret values or vault paths appearing in arguments or outbound content), unauthorized data collection, individual profiling, targeting of vulnerable users. Content checks that need judgement produce NEEDS_APPROVAL rather than a silent allow. Every decision carries reasons and policy ids.',
  '- Grants: authorize() returns a grant = HMAC over (action content hash, expiry, nonce, task id) with a key only the authorization service and the executor side can read; check_grant verifies binding, expiry and single use. A forged, expired, replayed or mismatched grant is rejected (tests).',
  '- harness/auth/approvals.py: persistent approval queue (pending / approved / rejected, who, when, note, preview of exactly what would be executed; approval binds to the action hash so an edited action needs a new approval), expiry, listing for the dashboard, resolve_approval.',
  '- harness/auth/limits.py: persistent spending / rate / resource accounting updated by record(action, result); exhaustion makes authorize return DENY with a resource reason; state survives restart.',
  '- harness/auth/audit.py: append-only hash-chained audit log (every authorization decision, grant use, approval, limit event, stop, revocation, secret access by name) with a verifier function that detects any edit, deletion or reordering; file owned by the auth uid and not writable by the learner uid in separated mode.',
  '- harness/auth/vault.py: SecretBroker: secrets stored in a directory readable only by the auth uid (mode 0700 / files 0600), never returned to the learner; an executor asks for a named secret for a specific granted action and destination (the broker checks the grant and the destination binding); scrub(text) replaces any known secret value in observations / logs; a canary test proves no secret value can reach an Observation, a log line, an RPC response to the learner uid, or the sandbox uid. Revocation by scope.',
  '- harness/auth/stop.py: pause and emergency stop: a stop flag that every authorize / check_primitive consults first (file based so it works across processes and survives restart), revoke(scope), and an operator-only reset.',
  '- harness/auth/untrusted.py: handling of environment content: a wrapper type for untrusted text, a guard that policy inputs are derived only from the typed ActionSpec (never from page text), detectors for instruction-like content in observations used only to LABEL the observation (the label is data for the learner and the operator; it grants nothing and blocks nothing by itself), and tests showing that pages / documents / tool outputs containing injected instructions (change the goal, raise your limits, print credentials, approve yourself, call this URL) cannot alter the task, the policy, the limits, the approvals or the vault.',
  '- harness/auth/service.py: process entry point (python -m cam_live.harness.auth.service --run-dir R --socket R/sock/auth.sock --policy <yaml>) exposing PolicyEngine over cam_live.harness.rpc with peer-uid checks: the learner uid may call authorize / check_grant / approvals (read) / stopped / limits_state; only the executor uid may call check_primitive / record / secret access; only the operator (root) may call resolve_approval / emergency_stop reset / revoke / policy reload.',
  '- harness/auth/launcher.py: starts the separated services as their own uids per cam_live.harness.SERVICE_USERS and SERVICE_MODULES (creates users with ensure_service_users, prepares the run directory with the right ownership and modes: sock/ , vault/ (auth only), audit log (auth only), verifier log (verifier only), browser profile (browser uid only), sandbox workspace (sandbox uid), learner state (learner uid)), supervises them, restarts crashed services, and stops everything on emergency stop. API: launch(run_dir, services=None, config=None) -> handle with status(), stop(). The modules for exec, verifier and learner are written by other workstreams; test your launcher with your own auth service and small test services.',
  '',
  'This instance is an unprivileged container without user namespaces or CAP_NET_ADMIN: say precisely in docs/EA/SECURITY.md what is enforced by the kernel (uids, file modes, Landlock, seccomp), what is enforced only by the policy path (per-destination network scoping), and what a VM deployment would add. A reference permission engine exists in /workspace/agentrs/src/agentrs/harness/policy.py and gateway.py and /workspace/agentrs/config/permissions.yaml (it needs sqlalchemy; do not copy that dependency).',
  '',
  'Tests (tests/harness/auth/; privileged-marked ones really create the users and really switch uid in subprocesses): every rule family allow / deny / needs-approval; fail-closed on malformed policy and unknown tools; grants; approvals bound to hashes; limits and persistence; audit chain tamper detection; vault canary and uid isolation (learner and sandbox uids cannot read vault, audit, verifier files; reading attempts fail with EACCES); emergency stop blocks all modalities immediately and survives restart; circumvention detector (denied browser action re-issued as code or api is denied); injection tests; RPC peer-uid authorization matrix; launcher starts, supervises and stops services.',
].join('\n')

const ES = common('ES', 'src/cam_live/harness/skills.py, harness/modality.py, harness/failures.py, harness/publishing.py, harness/discord.py, harness/http_api.py, harness/staging_discord/, tests/harness/skills/', HARN + ', Part 13 (1806-1911)') + [
  'YOUR JOB: Workstream ES: acquired executable skills, adaptive execution-modality selection, execution-failure taxonomy, the authorized publishing adapter, the Discord adapter and the generic HTTP API executor. Parallel workstreams: EB (environment adapter and browser), EC (sandbox, visual), EA (authorization). You integrate only through contracts.ModalityExecutor, ExecContext and PolicyEngine. For tests, write small real executors of your own (for example a tiny local HTTP application driven through your http_api executor) rather than depending on other workstreams.',
  '',
  'Deliver:',
  '- harness/skills.py: the skill library (modality "skill", tools skill.run plus read-only skill.list / skill.describe). A Skill has: id, semantic description, executable implementation as a typed program of ActionSpec steps with named parameters, typed arguments (JSON Schema), preconditions and postconditions as contracts.VerificationCondition, required permission scopes (the union of its steps; never more), expected cost, validation history, reliability estimate (Beta posterior with a credible interval), version, failure and recovery conditions, provenance (which successful traces it was abstracted from). Skill induction from experience: given successful ActionResult traces (lists of PrimitiveOp with arguments and observations) identify the reusable segment, abstract constants that vary between traces into parameters (alignment of two or more traces; with a single trace, arguments that came from the action inputs become parameters), generate the candidate procedure, derive pre / postconditions from the observed before / after states, validate it by executing it in an authorized environment through the normal ModalityExecutor path with fresh arguments, and only then register it. Execution expands a skill into its primitive steps, each passing ExecContext.check, so a skill never gains permission. Monitoring: each run updates reliability; a skill whose reliability falls below a threshold or whose postcondition fails repeatedly after an interface change is marked stale, then repaired (re-induction from new successful traces, version bump) or retired; never silently reused. Persistent storage with versions. Skill generation cannot touch the authorization system or the verifier (enforced by scope checks and tested).',
  '- harness/modality.py: adaptive execution selection (12A.7): for an intended operation with several feasible realisations (validated skill, structured browser, authorized API, lightweight visual grounding, heavier visual model) keep calibrated per-context estimates of success probability, latency, compute, number of primitive operations and failure / recovery cost (Bayesian estimates with the spec ordering as the prior), choose by expected cost of success with exploration, record the choice with its probabilities, and update from results. Features for context are generic (tool, site host hash, element role, observation properties), not task-specific. A denial is never a reason to try another modality: HARD failure classes remove the intent, not just the modality (tested). Expose the estimates as quantities so the learner can also learn from them.',
  '- harness/failures.py: classification of execution failures into contracts.FailureClass from observable evidence (exceptions, HTTP status, timeouts, stale ids, verification mismatch, policy denials, page-structure hashes), a bounded retry policy for transient classes with backoff, no retry for MISSING_PERMISSION / PLATFORM_RESTRICTION, and a structured failure observation the learner ingests. No hard-coded recovery decision tree beyond retry bounds: what to do next is the learner decision.',
  '- harness/http_api.py: the api executor (modality "api"): authorized HTTP requests to documented APIs with per-request ExecContext.check on method + URL, secrets injected by reference from ExecContext.secrets (the action arguments contain a secret NAME, never a value), response digesting into Observations with exact quantities, rate-limit header handling.',
  '- harness/publishing.py: the authorized publishing adapter: tools publish.draft, publish.preview, publish.submit, publish.update, publish.status for owned destinations (an owned static website directory; owned community channels through the Discord adapter). Draft -> preview (exact rendering of what would be published and where) -> submit, which goes through authorization and lands in the approval queue when the policy says so -> publish on approval -> status. Content is whatever the agent wrote; the adapter adds no template, schedule or strategy. Aggregate analytics ingestion for owned destinations (for example page visit counts from the owned site access log) as exact quantities with provenance.',
  '- harness/discord.py: the Discord adapter over the official bot REST API only (https://discord.com/developers/docs ; read https://discord.com/guidelines and the Developer Policy linked in the spec first and encode the constraints that matter in docs/ES/DISCORD_COMPLIANCE.md). DiscordClient(base_url, token_provider) with: guild(guild_id, with_counts=True), list_members(guild_id) paged, list_channels, create_channel, send_message(channel_id, content), list_invites(guild_id), create_invite(channel_id, ...), scheduled events, and rate-limit handling. Tools exposed to the agent describe capabilities only. Never automates user accounts; never reads direct messages; message content is neither stored nor made available for training unless TaskSpec.data_permissions allows it (default: content dropped at the adapter, only aggregate counts kept); member data reduced to what verification needs (id hash, bot flag, joined_at, pending flag) with no profiling. Without a bot token and guild authorization the tools report available=False with the exact reason, and nothing attempts a network call.',
  '- harness/staging_discord/: a local staging server implementing the subset of the Discord REST API your client uses (same paths, payload shapes, auth header, rate-limit headers, error codes) with test hooks to add / remove human members, bot members and operator-declared test accounts, so contract tests and the independent membership verifier can run without any real Discord call. It is labelled staging everywhere; results obtained against it are never reported as live.',
  '',
  'Tests (tests/harness/skills/): skill induction from two traces yields a parameterised procedure that succeeds with new arguments; single-trace induction; validation failure prevents registration; a skill cannot run a step its caller is not permitted to run; reliability tracking; staleness detected after the application changes its interface, repair produces a new working version, unrecoverable skills are retired; measured comparison of primitive-only versus skill-based execution on a repeated task (number of primitive decisions, latency) written to docs/evidence/ES/skills_vs_primitives.json; modality estimates calibrate on a simulated mix and selection shifts accordingly; denial never causes a modality switch; failure classification for each class; bounded retries; publishing flow with approval required / approved / rejected; Discord client against the staging server (members with bots and test accounts, invites, channels, messages, rate limits); message content dropped by default; unavailable tools without credentials.',
].join('\n')

const F = common('F', 'src/cam_live/runtime/, tasks/, tests/runtime/', 'the autonomous obstacle resolution section (1780-1805), Part 13 (1806-1911), Part 14 (1912-2025), Part 15 (2026-2115), Part 17 (2278-2339), sections 11.3 and 11.4 (inside 1103-1174)') + [
  'YOUR JOB: Workstream F: the persistent live runtime. It drives any contracts.AgentAPI through the 17-step event loop of spec 15.1 against any contracts.EnvironmentAdapter + PolicyEngine + OutcomeVerifier. The integrated neural agent (cam_live.agent.build_agent(cfg, run_dir) -> AgentAPI) is written by the master after this wave; build and test the runtime against the AgentAPI protocol with a small real agent of your own under tests/runtime/ (for example uniform choice over schema-valid candidates in cam_live.diagnostics.world.LabWorld, with honest bookkeeping), and against LabWorld + LabVerifier + AllowAllPolicy with SimClock.',
  '',
  'Deliver:',
  '- runtime/loop.py: LiveRuntime(agent, env, policy, verifier, task, run_dir, clock, cfg) implementing exactly the steps: receive objective; observe authorized world state; process new evidence (env.poll_events with a persisted cursor); reconcile matured pending outcomes (env.measure / verifier.measure for due queries; verifier.verify for the objective; signature checked before anything is passed to agent.reconcile as verified); agent.update_beliefs; agent.propose from env.discover_tools; agent.evaluate (predictions registered and written to predictions.jsonl BEFORE execution); agent.select; env.validate_action then policy.authorize; execute, or queue for approval and continue with other work (an action awaiting approval is not re-proposed in a loop; when approved later it is executed once; rejected ones are reported to the agent as a DENIED result); record observations; agent.internal_rewards; agent.learn; agent.meta_learn; save state atomically; then continue only when meaningful work or new observations exist, otherwise sleep until agent.next_wake / the next due outcome / an operator command (no busy polling, no activity generated to fill time). Failures of any action flow back as observations and ObstacleRecords and the same loop decides what to do next (no recovery decision tree here). Enforces TaskSpec.limits and stop conditions (duration, money, compute, external actions, decisions): on exhaustion or verified success it checkpoints the complete learner state and pauses. Crash safety: the persisted state (cursor, pending approvals, in-flight action id, counters) lets a restarted process resume without re-executing an action that already ran (use the environment de-duplication by action id) and without losing matured outcomes.',
  '- runtime/logs.py: RunLog writing the files named in contracts.RunFiles (events, decisions, experiments, predictions, learning_updates, meta_updates, obstacles as JSONL; append-only, fsync on consequential records), with redaction of secret values and of prohibited personal information (configurable patterns; member identifiers hashed), accurate timestamps from the Clock, and provenance fields. runtime/journal.py: the human-readable lifetime research journal (journal.md) regenerated from the structured records: current objective, attempts, what succeeded, what failed, what is uncertain, how the approach changed, apparent new capabilities with the evidence that supports them; every statement tagged as observed fact (with record ids) or inferred hypothesis; never states that learning happened unless a LearningUpdateRecord with a behavioural change supports it.',
  '- runtime/tasks.py: YAML -> TaskSpec with validation: rejects any key in TaskSpec.FORBIDDEN_KEYS or strategy-like content anywhere in the task file, requires explicit limits (duration, compute, money, authorized tools, data permissions, publishing authorization, stop conditions) for mode live, never assumes unlimited resources. tasks/discord_100.yaml: the first objective exactly as worded in spec 13.1, independently defined success criteria (100 distinct real human members who joined voluntarily; exclusion rules; evidence source), secondary metrics of 13.2, authorized resources as named placeholders the operator must fill (guild id, bot credential NAME in the vault, owned site), permitted interfaces, limits left unset-with-required markers so a live run refuses to start until the operator fills them, measurement protocol, data permissions (message content not stored / not trained on by default). No strategy of any kind. Also tasks/lab_staging.yaml for LabWorld / staging runs and one clearly different second objective file for transfer evaluation scaffolding (for example a software-utility objective on the staging services) with its own verifier configuration.',
  '- runtime/verifier.py: the independent verifier for membership objectives (implements contracts.OutcomeVerifier; not a model): reads members through a MembershipSource protocol you define (list_members() -> records with id, bot flag, joined_at, pending / unverified flag, and optional invite attribution), excludes bots, operator-declared test accounts, duplicate or artificial accounts where identifiable (rules as data; each exclusion counted in VerifiedOutcome.excluded), reports uncertainty when authenticity cannot be established (for example accounts that cannot be distinguished from automated ones, purchased-membership indicators the operator flags) and returns PENDING rather than ACHIEVED when the lower confidence bound is under the target; computes the secondary metrics (seven-day retention, voluntary participation counts, consented feedback counts, operating cost, time) as Quantities kept separate from the primary objective; signs outcomes with a key file only the verifier uid can read; appends every evaluation to a hash-chained verifier log. runtime/verifier_service.py: process entry (python -m cam_live.runtime.verifier_service --run-dir R --socket R/sock/verify.sock) over cam_live.harness.rpc exposing verify / measure / check_signature, plus a RemoteVerifier client.',
  '- runtime/scheduler.py: pending-outcome queue and wake scheduling (WallClock sleeping that is interruptible by operator commands; SimClock stepping for tests); runtime/control.py: operator commands through the run directory control file and through PolicyEngine (pause, resume, stop, approve, reject, assign next objective); runtime/obstacles.py: ObstacleRecord creation and linking to the learning updates that followed.',
  '- runtime/multi.py: the future multi-actor design made concrete: several actors, each with its own objective, local beliefs, experience history, authorization and environment, sharing one central learner (experience flows to the learner; weights flow back with versions); one actor is used now; a test runs two LabWorld actors against one shared learner object to prove the plumbing. No multiple public identities.',
  '- runtime/dashboard.py: FastAPI application (token-protected; bind to 127.0.0.1) reading the run directory: current objective, verified progress, current activity, recent experiments, predicted versus actual outcomes, internal reward statistics, calibration, recent learning updates, meta-learning status (including bootstrap mix and skipped-update reasons), resource consumption against limits, pending approvals with previews, current checkpoint, health; controls: pause, resume, stop, approve, reject, inspect logs, export checkpoint, assign a subsequent objective. One self-contained HTML page plus JSON endpoints; no strategy input field anywhere.',
  '- runtime/doctor.py and runtime/preflight.py: doctor inspects hardware (GPU, memory, disk, whether storage is persistent), model availability (backbone snapshot, grounding models), dependencies, Chromium, sandbox capabilities, service users, harness configuration. preflight produces the live-readiness report: every missing credential, authorization record, platform integration, limit or data permission listed explicitly; live operation is BLOCKED unless all are present; staging readiness is reported separately. Nothing here ever reports live readiness from staging or mock responses.',
  '- runtime/cli.py: the cam-live command (entry point cam_live.runtime.cli:main, also python -m cam_live.runtime.cli) with every command of spec Part 17: doctor; init --config; test (runs the pytest suites and records JUnit under docs/evidence/test_results/); validate --mode staging (calls cam_live.validation.run_staging(cfg) -> report dict, a master-owned module that lands at integration: import it inside the command); inspect-harness (lists tools, permissions, missing integrations from env.discover_tools / get_capabilities and the policy); run --task (preflight, then starts the runtime as a persistent process: separated-uid mode through cam_live.harness.auth.launcher.launch when root, in-process mode otherwise or with --inproc; detaches with a pid file; refuses mode live without the operator authorization record); status; pause; resume; evaluate-transfer --checkpoint (calls cam_live.eval.transfer.main(args), lands later); export-checkpoint (through agent.save / the checkpoint export function cam_live.credit.checkpoint, see docs/D/API.md if present); verify-completion (calls cam_live.verify_completion.main(args), master-owned). runtime/loop_service.py: the learner process entry used by the launcher (builds the agent with the factory named by --agent-factory, default cam_live.agent:build_agent, connects RemoteEnvironment / RemotePolicy from cam_live.harness.service and RemoteVerifier, runs LiveRuntime).',
  '',
  'Tests (tests/runtime/): the full loop on LabWorld to verified success and to verified failure; predictions are on disk before the action executes (ordering proven from the logs); waiting consumes no agent decisions and no environment actions; delayed outcomes reconcile once; unsigned or tampered verified outcomes are refused; approval-required actions queue, execute once after approval, and are reported once after rejection; limits exhaustion checkpoints and pauses; kill -9 mid-run then resume continues without duplicate execution and without lost outcomes; pause / resume / stop; task validation rejects strategy keys and unset live limits; the Discord task file contains no strategy (mechanical scan); membership verifier excludes bots / test accounts / duplicates, reports uncertainty, refuses to claim success under uncertainty; journal facts carry record ids; redaction; dashboard endpoints and controls with a test client; doctor and preflight output (live blocked with the explicit missing list); CLI commands that do not need the integrated agent; two actors sharing one learner.',
].join('\n')

function stage2(id, body, s1, a) {
  return common(id, 'src/cam_live/' + ({B: 'predict', C: 'reward', D: 'credit'})[id] + '/, tests/' + ({B: 'predict', C: 'reward', D: 'credit'})[id] + '/', ({
    B: 'Part 3 (390-449), Part 4 (450-518), Part 5 (519-577), Part 6 (578-671), Part 8 (872-908), section 11.1',
    C: 'Part 7 (672-871) in full, Part 8 (872-908), section 11.4, sections 16.5-16.6',
    D: 'Part 2 (295-389), Part 9 (909-1016), Part 10 (1017-1102), section 12A.9, section 15.2',
  })[id]) + [
    'YOUR JOB: Workstream ' + id + ' stage 2 of 2. Stage 1 (another agent, same workstream) built the tensor-level / model-independent parts in your directory; Workstream A has now delivered the real model. You wire your workstream onto the real model, exercise it end to end at debug scale on CPU (CamLiveConfig.debug(): tiny random backbone, debug core) in the LabWorld diagnostic environment, and run the gpu-marked checks on the real Qwen3-4B configuration where stated. Read docs/' + id + '/API.md and the stage-1 code first, then docs/status/A.json and src/cam_live/nn/model.py. Also read src/cam_live/learning_api.py (LossProvider, DecisionBatch, encode_decisions: the shared way to turn stored experience into tensors) and src/cam_live/diagnostics/collect.py (master-owned helper that runs a behaviour policy in LabWorld and writes ExperienceRecords with items, candidates, propensities, results and matured outcomes into an ExperienceStore; if it is missing or broken, write your own collector inside your tests and file a change request).',
    '',
    'Stage-1 summary of your workstream:',
    String(s1 || '(no summary returned: inspect the directory and docs/status)'),
    '',
    'Workstream A summary (model API and measured numbers):',
    String(a || '(no summary returned: inspect src/cam_live/nn and docs/status/A.json)'),
    '',
    body,
    '',
    'Other stage-2 agents (B, C, D) are working in parallel on predict/, reward/ and credit/. Use their stage-1 APIs as documented in docs/B/API.md, docs/C/API.md, docs/D/API.md; do not edit their files; if you need something from them, wrap it locally and file a change request. Update docs/' + id + '/API.md and docs/status/' + id + '.json so they describe the final state of the whole workstream (stage 1 + stage 2).',
  ].join('\n')
}

const B2body = [
  'Deliver (workstream B, on the real model):',
  '- predict/providers.py: LossProviders (cam_live.learning_api.LossProvider): WorldModelLoss (NLL of matured outcomes of the chosen action through encode_decisions -> z, encode_queries, features, your WorldHeads and the fast Bayesian layer; pending / unobservable masked via learning_api.matured_outcomes; latent-consistency term for the transition head; per-kind balancing), EvaluatorLoss (success BCE-with-logits against signed verified objective outcomes applied to all earlier prefixes; distributional heads; never trained on unverified or pending objectives), an ALPaCA-style FastPriorLoss if Workstream A exposes the differentiable posterior (train features and prior through online updates within one world context), and slow-timescale variants that request with_grad_semantic batches so the semantic adapters receive gradient from prediction losses.',
  '- predict/predictor.py: the runtime-facing API the integrated agent calls: Predictor(model, fast_state, registry, clock, cfg) with evaluate_candidates(context_items, goal_text, candidates, queries) -> List[CandidateEvaluation] carrying registered PredictionRecords (multi-horizon, per kind, epistemic and aleatoric uncertainty, p_success, value, VOI, cost), observe_outcomes(...) performing the immediate fast-belief update from matured outcomes and returning surprise and belief change, and resolve(...) filling prediction records. Predictions are written to the registry before the method returns, with made_at from the clock.',
  '- predict/policy.py additions: DecisionMaker(model, cfg): select(evaluations, mode=...) -> contracts.Decision with exact probabilities, exploration rule name, chosen index, a concise rationale assembled from the recorded numbers, and diagnostics (latent norms, top candidate values, uncertainty); the randomised-experiment path that registers an ExperimentRecord with arms and assignment probabilities; a test on the real model that permuting the belief latent changes the action distribution (KL well above numerical noise) while the backbone weights are fixed, and that changing only experiential weights changes decisions.',
  '- predict/planner.py: latent imagination with the transition head: evaluate alternative feasible actions over short horizons with uncertainty propagation; horizon adapts to measured multi-step error on held-out real transitions; outputs flagged imagined and rejected by any outcome API (test).',
  '- predict/candidates.py additions: BackboneProposer: uses model.generate with the latent bridge and your prompt builder over discovered ToolDescriptors to propose typed ActionSpecs (strict JSON), merged with the schema-walker proposals and any skill proposals passed in, de-duplicated, each with provenance; works with the tiny backbone in tests (mostly unparseable output is expected there: the merged set must still be valid and non-empty) and is exercised with the real Qwen3-4B in a gpu-marked test that reports the fraction of parseable, schema-valid proposals on LabWorld tools and on a list of generic browser / code tool descriptors (write docs/evidence/B/proposals_real_backbone.json).',
  '- Learning evidence at debug scale on LabWorld (slow-marked tests plus a script python -m cam_live.predict.diagnose writing docs/evidence/B/diagnostics.json): (1) the world model trained on collected experience beats a marginal (action-independent) baseline in held-out NLL on action-attributed counts and predicts at two horizons; (2) within a new world, fast belief updates reduce prediction error over the first K observations without any gradient step, compared with no adaptation; (3) evaluator calibration (Brier, slope) on prospectively registered success predictions across many short LabWorld lifetimes, before and after training; (4) VOI: the probe action has higher computed VOI than the noisy-gauge action and choosing by VOI-aware selection reaches the target with fewer interventions than greedy on average (report honestly with studentised intervals over seeds; if it does not, say so); (5) action quality versus raw outcome on lucky / unlucky outcomes.',
].join('\n')

const C2body = [
  'Deliver (workstream C, on the real model):',
  '- reward/inner.py: PolicyImprovementLoss, a LossProvider with timescale frequent: L_inner(theta; psi, D) = - sum log pi_theta(a | b, C) * A_psi + c_v * value loss on intrinsic returns - entropy bonus, where intrinsic rewards come from the RewardMixer (learned R_psi and labelled bootstrap) computed from the signal vector (assemble signals from the predict workstream outputs and the stored records; document every signal source) and credited returns use duration-aware discounting; R_psi outputs are detached here, so this loss can never move psi. The SAME function in functional form (parameters passed as a dictionary over the adaptable subset: the CandidatePolicy head plus the model decision trunk) is what the meta unroll differentiates.',
  '- reward/metalearner.py: MetaLearner(model, store, cfg): on every real policy update it snapshots the adaptable subset and records the support batch ids and inner hyperparameters; it maintains support / query windows (reward/windows.py) over the single lifetime; when a query window has at least the configured number of independent signed verified outcomes it recomputes theta_K(psi) functionally from the snapshot on cached latents (encode_decisions with grad=False), evaluates the outer surrogate on query decisions (on-policy when the logged propensities match pi_theta_K within tolerance, otherwise clipped importance weighting with the support check), backpropagates to psi, applies the per-group clipped outer step with the reward optimizer, bumps the reward version, updates the bootstrap mix through the promotion rule on held-out query evidence, and returns a contracts.MetaUpdateRecord (also for skipped updates, with the reason). Verified utility comes only from signed outcomes and verified measurements.',
  '- reward/selfgoals.py: the goal-free autonomous learning mode: proposes budgeted learning goals from epistemic uncertainty and achievable learning progress, tracks whether they were achieved by observation, discounts repeated trivial goals, enforces a fixed resource budget, and records usefulness against later independently assigned objectives.',
  '- Evidence at debug scale (float64 where needed; slow-marked tests plus python -m cam_live.reward.diagnose writing docs/evidence/C/diagnostics.json): (1) on the real model adaptable subset, the meta-gradient to every reward parameter is nonzero, matches finite differences of the outer surrogate (relative error reported) for K in 1,2,4, becomes exactly zero when the intrinsic reward is detached in the inner loss or when theta_K is detached, and the inner update measurably changes the policy action probabilities; (2) the inner loss leaves psi bit-identical; (3) a multi-lifetime LabWorld experiment (many short worlds drawn from the family; support then query within each lifetime; outer updates across lifetimes) comparing three learners with equal experience: bootstrap reward only, learned reward with meta-updates, and verified-outcome-only policy gradient; report learning curves of verified goal achievement with studentised intervals over seeds and state plainly whether the learned reward helped, did nothing or hurt; also report what the learned reward pays for (key / unlock action, probe, noisy gauge); (4) integrity: the noisy gauge does not attract sustained reward; fabricated, unsigned, duplicated or imagined outcomes never enter the outer objective; scaling reward magnitude does not change the selected update direction beyond the bound; (5) cost of a meta-update at the 50m preset on GPU (cached latents, K = 2 and 4): time and memory, gpu-marked, under the shared lock, written to docs/evidence/C/meta_cost_50m.json.',
].join('\n')

const D2body = [
  'Deliver (workstream D, on the real model):',
  '- credit/learner.py: ContinualLearner(model, store, cfg): owns one optimizer per parameter group (experiential, heads, semantic_adapters; the reward group is never given to it), per-group gradient clipping, learning-rate schedules, and the three timescales: frequent updates of experiential + heads triggered by matured informative outcomes (an UpdatePlan from cam_live.learning_api; not by wall-clock and not once per correlated row), slow updates of the semantic adapters every cfg.optim.adapter_every frequent updates using with_grad_semantic batches under gradient checkpointing, and no gradient at the fast timescale. It iterates over registered LossProviders (register(provider)), balances loss magnitudes so no single loss supplies more than about 90 percent of the experiential gradient norm (measure and log the shares), mixes replay strata from the store, keeps a held-out validation split of matured experience, and returns contracts.LearningUpdateRecord objects with: trigger, losses, parameter groups actually changed, per-group gradient norms, before / after group hashes, per-group weight-delta norms, experience ids, credit changes, and a behavioural probe (predictions and action probabilities on a fixed probe batch before and after: an update that changes hashes but not behaviour is flagged).',
  '- credit/providers.py: LossProviders for the return decomposer (RUDDER regression on matured verified returns from decision-level latents of a trajectory) and the hindsight model (COCOA), plus CreditAssigner: given matured outcomes and links it computes, stores and versions per-decision credit in ExperienceRecord.credit / credit_uncertainty for each estimator (simple attribution, RUDDER return-to-go, COCOA where supported), performs the retrospective update of earlier experiences when an outcome matures, exposes the credited returns used by the reward workstream policy loss, applies duration-aware discounting, and uses credit/select.py to choose the default by evidence.',
  '- credit/retention.py: retention: an anchor set of earlier-objective experience with stored reference outputs; functional regularisation on the anchors plus replay; measure_forgetting(...) reporting the change of prediction NLL / calibration / decision agreement on earlier objective families after learning a new one; hooks for checkpoint promotion.',
  '- credit/checkpoint.py additions: save / load of the complete learner state for the real CamLiveModel (trainable groups, optimizers, fast state, lifetime context, sampler state, schedules, RNG, versions, architecture signature), promotion / rollback wired to validation and retention metrics, weights-only export and a loader that builds a fresh model from configuration plus exported weights with empty experience and reset fast beliefs.',
  '- Evidence at debug scale (slow-marked tests plus python -m cam_live.credit.diagnose writing docs/evidence/D/diagnostics.json): (1) real gradient updates from stored LabWorld experience change the experiential group and the heads (hashes, delta norms) AND improve held-out prediction NLL; (2) the slow path gives the semantic adapters (LoRA and bridge) nonzero gradient and a nonzero weight delta from experience-grounded losses; (3) delayed credit in LabWorld with the unlock -> last-channel dependency: when the delayed adopters mature, the earlier unlock decision is retrospectively credited by RUDDER return-to-go and (where supported) by COCOA, return conservation holds under duration-aware discounting, nothing is credited before maturation, and no outcome is linked to a later decision; compare the estimators with the randomised difference (worlds with and without unlock) and report which the selector promotes; (4) retention: train on family A, then family B (different mechanism), measure forgetting on A with and without the retention mechanism; (5) restart recovery: kill -9 the training process mid-update and resume from the last atomic checkpoint with identical subsequent results to an uninterrupted run from that checkpoint; (6) fresh-process weights-only reload reproduces predictions bit-exactly with no experience available; (7) gpu-marked, under the shared lock, real Qwen3-4B + 50m core: one frequent update and one slow adapter update on a small stored batch, reporting time, memory, per-group gradient norms and deltas (docs/evidence/D/real_update.json).',
].join('\n')

phase('Build')
const aP = agent(A, { label: 'A neural architecture', phase: 'Build' })
const b1P = agent(B1, { label: 'B1 prediction (tensor level)', phase: 'Build' })
const c1P = agent(C1, { label: 'C1 reward + meta-gradient math', phase: 'Build' })
const d1P = agent(D1, { label: 'D1 store, credit refs, checkpoints', phase: 'Build' })
const harnessP = parallel([
  () => agent(EB, { label: 'EB environment + browser + staging', phase: 'Build' }),
  () => agent(EC, { label: 'EC sandbox + visual + grounding', phase: 'Build' }),
  () => agent(EA, { label: 'EA authorization + isolation', phase: 'Build' }),
  () => agent(ES, { label: 'ES skills + publishing + Discord', phase: 'Build' }),
  () => agent(F, { label: 'F live runtime', phase: 'Build' }),
])

const a = await aP
log('A (model) returned; starting model-integration stage for B, C, D as their stage 1 completes')

const stage2P = parallel([
  async () => { const s = await b1P; return agent(stage2('B', B2body, s, a), { label: 'B2 prediction on real model', phase: 'Model integration' }) },
  async () => { const s = await c1P; return agent(stage2('C', C2body, s, a), { label: 'C2 reward on real model', phase: 'Model integration' }) },
  async () => { const s = await d1P; return agent(stage2('D', D2body, s, a), { label: 'D2 learner on real model', phase: 'Model integration' }) },
])

const [harness, s2] = [await harnessP, await stage2P]
const names = ['EB', 'EC', 'EA', 'ES', 'F']
const out = { A: a, B1: await b1P, C1: await c1P, D1: await d1P }
names.forEach((n, i) => { out[n] = harness[i] })
;['B2', 'C2', 'D2'].forEach((n, i) => { out[n] = s2[i] })
return out
